/* ============================================================================
 * 睿游幼教云 · 自包含单文件后端 v1.2（P0 止血加固版 · 由修复后源码重建）
 *   ✗ 不再注入 RUI_BOOTSTRAP_PW=admin123、不再有任何 fixture 开关
 *   ✗ 不再内置任何 JWT_SECRET；弱/缺失密钥直接拒绝启动
 *   ✗ 不再内嵌固化弱口令的预烘焙库；首次启动由 db.open() 现场生成
 *     CSPRNG 强随机初始口令，落在 <DATA_DIR>/initial_admin_password.txt (0600)
 *   ✓ 强制外部注入 JWT_SECRET(>=32字节) 与 RUI_WHITELIST(完整 Origin，禁止 *)
 *   ✓ CORS 白名单 / fixture 注入 / 弱密钥三道守卫由 gateway.js 启动块再校验一次
 *   ✓ LLM PII 生产态恒 enforce（名单兜底 + 残留 fail-closed）
 *   ✓ 智采 data.json 全量假数据化；运行时 tenant_id 一律取自 JWT
 *   ✓ FROZEN DDL 内联注入，单文件真正自包含
 * ============================================================================ */
(function () {
  var path = require("path"), os = require("os"), fs = require("fs");
  var EMBED = {"saas_db_b64":"","corpus":{"lex-blacklist.js":"","lex-quality.js":"","lex-redline.js":"","lz_corpus.js":"","lz_dispositions.js":"","lz_engine.js":"","lz_guide.js":"","lz_lexicon.js":"","lz_methods.js":"","lz_vivid.js":"","scene_alias.js":"","seed_recs.js":""},"zhicai":{"index.mjs":"","data.json":""},"sqljs_wasm_b64":"","frozen_ddl_b64":""};
  var DATA_DIR = process.env.RUI_STANDALONE_DIR || path.join(os.tmpdir(), "ruiedu-standalone-v12");
  fs.mkdirSync(path.join(DATA_DIR, "corpus"), { recursive: true });
  fs.mkdirSync(path.join(DATA_DIR, "plugins", "zhicai"), { recursive: true });
  Object.keys(EMBED.corpus).forEach(function (n) {
    fs.writeFileSync(path.join(DATA_DIR, "corpus", n), Buffer.from(EMBED.corpus[n], "base64"));
  });
  Object.keys(EMBED.zhicai).forEach(function (n) {
    fs.writeFileSync(path.join(DATA_DIR, "plugins", "zhicai", n), Buffer.from(EMBED.zhicai[n], "base64"));
  });
  process.env.DB_DRIVER = "sqlite";
  process.env.SAAS_DB = path.join(DATA_DIR, "saas.db");
  process.env.RUI_DATA_DIR = DATA_DIR;
  process.env.LZ_CORPUS_DIR = path.join(DATA_DIR, "corpus");
  process.env.ZHICAI_PLUGIN_ENTRY = path.join(DATA_DIR, "plugins", "zhicai", "index.mjs");
  process.env.RUI_SNAPSHOT = path.join(DATA_DIR, "snap.json");
  process.env.SQLJS_WASM_B64 = EMBED.sqljs_wasm_b64;
  process.env.RUI_FROZEN_DDL_B64 = EMBED.frozen_ddl_b64;
  process.env.DEEPSEEK_API_KEY = process.env.DEEPSEEK_API_KEY || "";
  ["RUI_BOOTSTRAP_PW", "RUI_FIXTURE", "RUI_DEMO_ACCOUNTS", "RUI_ALLOW_DEFAULT_SECRET"].forEach(function (k) {
    delete process.env[k];
  });
  var sec = String(process.env.JWT_SECRET || "");
  if (sec.length < 32 || /CHANGE_ME|^(test|dev|secret|admin|123456)/i.test(sec)) {
    console.error("[boot][P0] JWT_SECRET 缺失或为弱密钥。请执行: export JWT_SECRET=$(openssl rand -hex 32)");
    process.exit(1);
  }
  var wl = String(process.env.RUI_WHITELIST || "").trim();
  if (!wl || wl.indexOf("*") >= 0) {
    console.error("[boot][P0] RUI_WHITELIST 必须显式配置为完整 Origin（如 https://你的正式域名.com），禁止 * / 留空。");
    process.exit(1);
  }
  process.env.RUI_PII_MODE = "enforce";
  process.env.STANDALONE_BOOT = "1";
  console.log("[boot][P0] v1.2 加固版：无内置密钥/口令、无 fixture 通道、CORS 白名单=" + wl);
  console.log("[boot][P0] 首次登录口令将在启动后写入 " + path.join(DATA_DIR, "initial_admin_password.txt"));
})();

