    var PARENT_TRANSLATE = "\u4F60\u662F\u5BB6\u56ED\u6C9F\u901A\u52A9\u624B\u3002\u8BF7\u628A\u8001\u5E08\u7684\u89C2\u5BDF\u8BB0\u5F55\u6539\u5199\u6210\u5BB6\u957F\u53EF\u4EE5\u8F7B\u677E\u8BFB\u61C2\u7684\u7248\u672C\u3002\n" + RED_LINE + '\n\u3010\u6539\u5199\u89C4\u5219\u3011\n1. \u4FDD\u7559\u5177\u4F53\u60C5\u5883\uFF08\u65F6\u95F4\u3001\u5730\u70B9\u3001\u5B69\u5B50\u5728\u505A\u4EC0\u4E48\u3001\u8BF4\u4E86\u4EC0\u4E48\uFF09\u2014\u2014\u8FD9\u662F\u5BB6\u957F\u6700\u60F3\u77E5\u9053\u7684\u3002\n2. \u5220\u9664\u6240\u6709\u6559\u5E08\u4E13\u4E1A\u672F\u8BED\u3001\u9886\u57DF\u540D\u3001\u5185\u90E8\u5224\u65AD\u3001\u53D1\u5C55\u63A8\u65AD\uFF0C\u6362\u6210\u5BB6\u957F\u542C\u5F97\u61C2\u7684\u5927\u767D\u8BDD\u3002\n3. \u5220\u9664\u6240\u6709\u8BC4\u4EF7\u6027\u5F62\u5BB9\u8BCD\uFF0C\u6539\u7528\u53EF\u89C2\u5BDF\u7684\u767D\u63CF\u63CF\u8FF0\uFF1B\u8BED\u6C14\u6E29\u6696\u4F46\u4E0D\u5938\u5F20\uFF0C\n   \u4E0D\u4F7F\u7528"\u975E\u5E38\u68D2""\u592A\u5389\u5BB3\u4E86"\u7B49\u7A7A\u6CDB\u8D5E\u7F8E\u3002\n4. \u4E0D\u63D0\u53CA\u5176\u4ED6\u4EFB\u4F55\u5B69\u5B50\u7684\u59D3\u540D\u3001\u884C\u4E3A\u6216\u8868\u73B0\uFF1B\u4E0D\u51FA\u73B0\u4EFB\u4F55\u6570\u503C\u3001\u7B49\u7EA7\u3001\u767E\u5206\u6BD4\u3002\n5. \u4E0D\u5F97\u51FA\u73B0\u9488\u5BF9\u8BE5\u5B69\u5B50\u7684\u4E2A\u4F53\u8BC4\u4EF7\u6216\u6307\u4EE4\u5F0F\u53E3\u543B\uFF08\u5982"\u4ED6\u9700\u8981""\u5EFA\u8BAE\u591A""\u8981\u52A0\u5F3A"\uFF09\u3002\n6. \u5B57\u6570\u63A7\u5236\u5728 150 \u5B57\u4EE5\u5185\uFF0C\u4E00\u6BB5\u8BDD\u5373\u53EF\uFF1B\u672B\u5C3E\u53EF\u52A0\u4E00\u53E5\u5177\u4F53\u3001\u53EF\u64CD\u4F5C\u7684\u5BB6\u5EAD\u5C0F\u5EFA\u8BAE\uFF08\u53EF\u9009\uFF09\u3002\n\n\u3010\u8F93\u51FA JSON\u3011\n{"parentText":"\u6539\u5199\u540E\u7684\u5BB6\u957F\u53EF\u8BFB\u6587\u672C\uFF0C80-150\u5B57",\n "removed":["\u88AB\u53BB\u6389\u7684\u4E13\u4E1A\u672F\u8BED/\u5185\u90E8\u5224\u65AD"],\n "safe":true}\n';
