  if (BAD_WHITELIST.length) {
    console.error("[gateway][CORS] \u81F4\u547D\uFF1ARUI_WHITELIST \u542B\u975E\u6CD5\u9879 " + JSON.stringify(BAD_WHITELIST) + "\uFF08\u7981\u6B62 * / \u7A7A / \u975E http(s)://host \u5F62\u5F0F\uFF09\u3002");
    process.exit(1);
  }
  if (!WHITELIST.length) {
    console.error("[gateway][CORS] \u81F4\u547D\uFF1A\u751F\u4EA7\u6001\u672A\u914D\u7F6E RUI_WHITELIST\u3002");
    console.error("[gateway][CORS] \u8BF7\u5728 .env \u5199\u5165\uFF1ARUI_WHITELIST=https://\u4F60\u7684\u6B63\u5F0F\u57DF\u540D.com");
    console.error("[gateway][CORS] \u5DF2\u62D2\u7EDD\u542F\u52A8 \u2014\u2014 \u7EDD\u4E0D\u5141\u8BB8\u65E0\u6761\u4EF6 Access-Control-Allow-Origin: *\u3002");
    process.exit(1);
  }
