app.use((req, res, next) => {
  const o = (req.header("Origin") || "").trim();
  const allowed = !!o && WHITELIST.indexOf(o) >= 0;
  if (allowed) {
    res.header("Access-Control-Allow-Origin", o);
    res.header("Vary", "Origin");
    res.header("Access-Control-Allow-Credentials", "true");
  }
  res.header(
    "Access-Control-Allow-Headers",
    "Content-Type,Authorization,X-RUI-Token,X-RUI-Tool,X-Tenant-ID,X-User-Role,X-RUI-Trace"
  );
  res.header("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
  if (req.method === "OPTIONS") {
    if (o && !allowed) {
      return res.status(403).json({ code: 1003, msg: "CORS: Origin \u4E0D\u5728\u767D\u540D\u5355", data: {}, traceId: req.traceId });
    }
    return res.sendStatus(204);
  }
  next();
});
