app.get("/api/v1/tenant/label_feedback", authJwt, async (req, res) => {
  await db.open();
  const tid = req.tenant_id;
  const rows = await db.all(
    `SELECT ai_original_label AS ai_label,
            teacher_final_label AS teacher_label,
            ai_local_label,
            ai_cloud_label,
            COUNT(*) AS n
       FROM records
      WHERE tenant_id = ? AND src IN ('ai','ai_demo')
        AND ai_original_label IS NOT NULL
        AND teacher_final_label IS NOT NULL
      GROUP BY ai_original_label, teacher_final_label
      ORDER BY n DESC`,
    [tid]
  );
  const total = rows.reduce((s, r) => s + Number(r.n || 0), 0);
  const changed = rows.filter((r) => r.ai_label !== r.teacher_label);
  const changedN = changed.reduce((s, r) => s + Number(r.n || 0), 0);
  ok(res, {
    tenant_id: tid,
    total_ai_records: total,
    changed_records: changedN,
    change_rate: total ? +(changedN / total).toFixed(3) : 0,
    /* 最常被改错的：规则库该补语料的地方 */
    top_mistakes: changed.slice(0, 10).map((r) => ({
      ai_label: r.ai_label,
      teacher_label: r.teacher_label,
      n: Number(r.n)
    }))
  }, req.traceId);
});
